import { useEffect, useRef, useState } from 'react';
import { StyleSheet, View } from 'react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withRepeat,
  withSequence,
  withSpring,
} from 'react-native-reanimated';
import { toZonedTime } from 'date-fns-tz';

import { colors } from '@/constants/colors';
import { spacing } from '@/constants/spacing';

interface Props {
  myTimezone: string;
  mySleepStart: string;
  mySleepEnd: string;
  partnerTimezone: string;
  partnerSleepStart: string;
  partnerSleepEnd: string;
}

/**
 * Parse "HH:mm" to { hour, minute }.
 */
function parseTime(t: string): { hour: number; minute: number } {
  const [h, m] = t.split(':').map(Number);
  return { hour: h, minute: m ?? 0 };
}

/**
 * Build a set of awake half-hour slots (0-47) in UTC for a given timezone and sleep window.
 * Using half-hour granularity to handle IST's +5:30 offset.
 */
function getAwakeSlots(
  timezone: string,
  sleepStart: string,
  sleepEnd: string,
): Set<number> {
  const now = new Date();
  const sleepStartParsed = parseTime(sleepStart);
  const sleepEndParsed = parseTime(sleepEnd);

  // Create dates in the partner's local timezone, then convert to UTC
  const today = toZonedTime(now, timezone);
  const year = today.getFullYear();
  const month = today.getMonth();
  const day = today.getDate();

  // Build sleep range in local half-hour slots (0-47)
  const sleepStartSlot = sleepStartParsed.hour * 2 + (sleepStartParsed.minute >= 30 ? 1 : 0);
  const sleepEndSlot = sleepEndParsed.hour * 2 + (sleepEndParsed.minute >= 30 ? 1 : 0);

  const sleepingSlots = new Set<number>();
  if (sleepStartSlot > sleepEndSlot) {
    // Sleep wraps midnight: e.g., 23:00 → 07:00
    for (let i = sleepStartSlot; i < 48; i++) sleepingSlots.add(i);
    for (let i = 0; i < sleepEndSlot; i++) sleepingSlots.add(i);
  } else {
    for (let i = sleepStartSlot; i < sleepEndSlot; i++) sleepingSlots.add(i);
  }

  // Convert awake LOCAL slots to UTC slots
  // Get the UTC offset for this timezone right now (handles DST)
  const utcNow = now.getTime();
  const zonedNow = toZonedTime(now, timezone);
  const offsetMs = zonedNow.getTime() - utcNow;
  const offsetSlots = Math.round(offsetMs / (30 * 60 * 1000));

  const awakeUTC = new Set<number>();
  for (let localSlot = 0; localSlot < 48; localSlot++) {
    if (!sleepingSlots.has(localSlot)) {
      const utcSlot = ((localSlot - offsetSlots) % 48 + 48) % 48;
      awakeUTC.add(utcSlot);
    }
  }

  return awakeUTC;
}

type SegmentType = 'both' | 'one' | 'neither';

function computeSegments(
  myTimezone: string,
  mySleepStart: string,
  mySleepEnd: string,
  partnerTimezone: string,
  partnerSleepStart: string,
  partnerSleepEnd: string,
): SegmentType[] {
  const myAwake = getAwakeSlots(myTimezone, mySleepStart, mySleepEnd);
  const partnerAwake = getAwakeSlots(partnerTimezone, partnerSleepStart, partnerSleepEnd);

  // We display 48 half-hour segments from user's local midnight
  const now = new Date();
  const utcNow = now.getTime();
  const zonedNow = toZonedTime(now, myTimezone);
  const offsetMs = zonedNow.getTime() - utcNow;
  const offsetSlots = Math.round(offsetMs / (30 * 60 * 1000));

  const segments: SegmentType[] = [];
  // Group into 24 hour-segments for display (average of 2 half-hour slots)
  for (let hour = 0; hour < 24; hour++) {
    const slot1 = ((hour * 2 + offsetSlots) % 48 + 48) % 48; // local→UTC for slot checking
    // Actually, we need to go local→UTC to check against the UTC awake sets
    // Local slot = hour*2, its UTC equivalent:
    const utcSlot0 = ((hour * 2 - offsetSlots) % 48 + 48) % 48;
    const utcSlot1 = ((hour * 2 + 1 - offsetSlots) % 48 + 48) % 48;

    const myAwakeHere = myAwake.has(utcSlot0) || myAwake.has(utcSlot1);
    const partnerAwakeHere = partnerAwake.has(utcSlot0) || partnerAwake.has(utcSlot1);

    if (myAwakeHere && partnerAwakeHere) {
      segments.push('both');
    } else if (myAwakeHere || partnerAwakeHere) {
      segments.push('one');
    } else {
      segments.push('neither');
    }
  }

  return segments;
}

const SEGMENT_COLORS: Record<SegmentType, string> = {
  both: colors.gold,
  one: colors.dawn,
  neither: colors.night,
};

const SEGMENT_OPACITY: Record<SegmentType, number> = {
  both: 0.7,
  one: 0.35,
  neither: 0.25,
};

export function TimezoneOverlapBar(props: Props) {
  const [segments, setSegments] = useState<SegmentType[]>(() =>
    computeSegments(
      props.myTimezone,
      props.mySleepStart,
      props.mySleepEnd,
      props.partnerTimezone,
      props.partnerSleepStart,
      props.partnerSleepEnd,
    ),
  );
  const [nowPosition, setNowPosition] = useState(0);
  const dotScale = useSharedValue(1);
  const intervalRef = useRef<ReturnType<typeof setInterval>>(undefined);

  useEffect(() => {
    setSegments(
      computeSegments(
        props.myTimezone,
        props.mySleepStart,
        props.mySleepEnd,
        props.partnerTimezone,
        props.partnerSleepStart,
        props.partnerSleepEnd,
      ),
    );
  }, [
    props.myTimezone,
    props.mySleepStart,
    props.mySleepEnd,
    props.partnerTimezone,
    props.partnerSleepStart,
    props.partnerSleepEnd,
  ]);

  // Update "now" position every 60s
  useEffect(() => {
    const updateNow = () => {
      const now = new Date();
      const zoned = toZonedTime(now, props.myTimezone);
      const fraction = (zoned.getHours() + zoned.getMinutes() / 60) / 24;
      setNowPosition(fraction);
    };
    updateNow();
    intervalRef.current = setInterval(updateNow, 60_000);
    return () => {
      if (intervalRef.current) clearInterval(intervalRef.current);
    };
  }, [props.myTimezone]);

  // Pulse animation for the dot
  useEffect(() => {
    dotScale.value = withRepeat(
      withSequence(withSpring(1.4, { damping: 8 }), withSpring(1, { damping: 8 })),
      -1,
      true,
    );
  }, []);

  const dotStyle = useAnimatedStyle(() => ({
    transform: [{ scale: dotScale.value }],
  }));

  return (
    <View style={styles.container}>
      <View style={styles.bar}>
        {segments.map((seg, i) => (
          <View
            key={i}
            style={[
              styles.segment,
              {
                backgroundColor: SEGMENT_COLORS[seg],
                opacity: SEGMENT_OPACITY[seg],
              },
              i === 0 && styles.firstSegment,
              i === 23 && styles.lastSegment,
            ]}
          />
        ))}
      </View>
      <Animated.View
        style={[
          styles.dot,
          { left: `${nowPosition * 100}%` },
          dotStyle,
        ]}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    marginTop: spacing[8],
    height: 10,
    justifyContent: 'center',
  },
  bar: {
    flexDirection: 'row',
    height: 3,
    borderRadius: 1.5,
    overflow: 'hidden',
  },
  segment: {
    flex: 1,
  },
  firstSegment: {
    borderTopLeftRadius: 1.5,
    borderBottomLeftRadius: 1.5,
  },
  lastSegment: {
    borderTopRightRadius: 1.5,
    borderBottomRightRadius: 1.5,
  },
  dot: {
    position: 'absolute',
    width: 5,
    height: 5,
    borderRadius: 2.5,
    backgroundColor: colors.rose,
    marginLeft: -2.5,
  },
});
