import { useEffect, useState } from 'react';
import { Alert, Share, StyleSheet, View } from 'react-native';
import { router } from 'expo-router';
import * as Haptics from 'expo-haptics';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withRepeat,
  withSpring,
  withSequence,
} from 'react-native-reanimated';

import { ScreenWrapper } from '@/components/ui/ScreenWrapper';
import { Text } from '@/components/ui/Text';
import { Input } from '@/components/ui/Input';
import { Button } from '@/components/ui/Button';
import { GlassCard } from '@/components/ui/GlassCard';
import { useAuth } from '@/lib/auth';
import { supabase } from '@/lib/supa';
import { spacing } from '@/constants/spacing';
import { springs } from '@/constants/animations';

type PairState = 'choose' | 'waiting' | 'join';

export default function PairScreen() {
  const auth = useAuth();
  const [state, setState] = useState<PairState>('choose');
  const [inviteCode, setInviteCode] = useState('');
  const [joinCode, setJoinCode] = useState('');
  const [loading, setLoading] = useState(false);

  // Pulse animation for "Waiting for your love..."
  const pulseOpacity = useSharedValue(1);
  const pulseStyle = useAnimatedStyle(() => ({
    opacity: pulseOpacity.value,
  }));

  useEffect(() => {
    if (state === 'waiting') {
      pulseOpacity.value = withRepeat(
        withSequence(
          withSpring(0.4, { damping: 25, stiffness: 80 }),
          withSpring(1, { damping: 25, stiffness: 80 }),
        ),
        -1,
        false,
      );
    }
  }, [state, pulseOpacity]);

  // Realtime subscription when waiting
  useEffect(() => {
    if (state !== 'waiting' || !auth.couple?.id) return;

    const channel = supabase
      .channel(`couple-${auth.couple.id}`)
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'couples',
          filter: `id=eq.${auth.couple.id}`,
        },
        async (payload) => {
          if (payload.new && (payload.new as any).partner_2) {
            Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
            await auth.refreshCouple();
            router.replace('/(auth)/setup');
          }
        },
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [state, auth.couple?.id, auth]);

  const handleCreateCouple = async () => {
    setLoading(true);
    try {
      const code = await auth.createCouple();
      setInviteCode(code);
      setState('waiting');
    } catch (e: any) {
      Alert.alert('Error', e.message);
    } finally {
      setLoading(false);
    }
  };

  const handleShareCode = () => {
    Share.share({
      message: `Join me on Close To You! My invite code is: ${inviteCode}`,
    });
  };

  const handleJoinCouple = async () => {
    if (joinCode.length !== 6) return;
    setLoading(true);
    try {
      await auth.joinCouple(joinCode);
      router.replace('/(auth)/setup');
    } catch (e: any) {
      Alert.alert('Error', e.message);
    } finally {
      setLoading(false);
    }
  };

  if (state === 'waiting') {
    return (
      <ScreenWrapper style={styles.centered}>
        <Text variant="title1" style={styles.textCenter}>
          Your invite code
        </Text>

        <Text
          variant="heroDisplay"
          style={[styles.textCenter, styles.codeDisplay]}
        >
          {inviteCode}
        </Text>

        <Animated.View style={pulseStyle}>
          <Text variant="romanticSub" color="inkSoft" style={styles.textCenter}>
            Waiting for your love...
          </Text>
        </Animated.View>

        <Button
          variant="secondary"
          onPress={handleShareCode}
          style={styles.shareButton}
        >
          Share code
        </Button>
      </ScreenWrapper>
    );
  }

  if (state === 'join') {
    return (
      <ScreenWrapper style={styles.centered}>
        <Text variant="title1" style={styles.textCenter}>
          Enter their code
        </Text>
        <Text variant="romanticSub" color="inkSoft" style={[styles.textCenter, styles.subtitle]}>
          the one your love shared with you
        </Text>

        <Input
          value={joinCode}
          onChangeText={(t) => setJoinCode(t.toUpperCase())}
          placeholder="ABC123"
          maxLength={6}
          autoCapitalize="characters"
          autoCorrect={false}
          style={styles.codeInput}
        />

        <Button
          onPress={handleJoinCouple}
          loading={loading}
          disabled={joinCode.length !== 6}
          style={styles.joinButton}
        >
          Join your love
        </Button>

        <Button variant="tertiary" onPress={() => setState('choose')}>
          Go back
        </Button>
      </ScreenWrapper>
    );
  }

  // choose state
  return (
    <ScreenWrapper style={styles.centered}>
      <Text variant="title1" style={styles.textCenter}>
        Connect with your love
      </Text>
      <Text variant="romanticSub" color="inkSoft" style={[styles.textCenter, styles.subtitle]}>
        choose how you'd like to start
      </Text>

      <View style={styles.cards}>
        <GlassCard onPress={handleCreateCouple} style={styles.card}>
          <Text variant="headline">Start a new couple</Text>
          <Text variant="subheadline" color="inkSoft" style={styles.cardSub}>
            Create an invite code for your partner
          </Text>
        </GlassCard>

        <GlassCard onPress={() => setState('join')} style={styles.card}>
          <Text variant="headline">Join your partner</Text>
          <Text variant="subheadline" color="inkSoft" style={styles.cardSub}>
            Enter the code they shared with you
          </Text>
        </GlassCard>
      </View>
    </ScreenWrapper>
  );
}

const styles = StyleSheet.create({
  centered: {
    justifyContent: 'center',
    alignItems: 'center',
  },
  textCenter: {
    textAlign: 'center',
  },
  subtitle: {
    marginTop: spacing[8],
  },
  cards: {
    width: '100%',
    gap: spacing[16],
    marginTop: spacing[32],
  },
  card: {
    alignItems: 'center',
  },
  cardSub: {
    marginTop: spacing[4],
    textAlign: 'center',
  },
  codeDisplay: {
    letterSpacing: 8,
    marginVertical: spacing[32],
  },
  shareButton: {
    marginTop: spacing[24],
    width: '100%',
  },
  codeInput: {
    fontSize: 24,
    letterSpacing: 8,
    textAlign: 'center',
    width: '100%',
    marginTop: spacing[24],
  },
  joinButton: {
    width: '100%',
    marginTop: spacing[24],
    marginBottom: spacing[12],
  },
});
