import {
  createContext,
  useContext,
  useEffect,
  useState,
  useCallback,
  ReactNode,
  createElement,
} from 'react';
import { Session } from '@supabase/supabase-js';

import { supabase } from './supa';
import type { Profile, Couple } from '@/types/database';

export type AuthStatus = 'loading' | 'unauthenticated' | 'unpaired' | 'paired';

interface AuthContextValue {
  session: Session | null;
  profile: Profile | null;
  couple: Couple | null;
  status: AuthStatus;
  signUp: (email: string, password: string) => Promise<void>;
  signIn: (email: string, password: string) => Promise<void>;
  signOut: () => Promise<void>;
  createCouple: () => Promise<string>;
  joinCouple: (code: string) => Promise<void>;
  updateProfile: (data: Partial<Profile>) => Promise<void>;
  updateCouple: (data: Partial<Couple>) => Promise<void>;
  refreshCouple: () => Promise<void>;
}

const AuthContext = createContext<AuthContextValue | null>(null);

export function useAuth(): AuthContextValue {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth must be used within AuthProvider');
  return ctx;
}

function deriveStatus(
  session: Session | null,
  couple: Couple | null,
  loading: boolean,
): AuthStatus {
  if (loading) return 'loading';
  if (!session) return 'unauthenticated';
  if (!couple || !couple.partner_2) return 'unpaired';
  return 'paired';
}

export function AuthProvider({ children }: { children: ReactNode }) {
  const [session, setSession] = useState<Session | null>(null);
  const [profile, setProfile] = useState<Profile | null>(null);
  const [couple, setCouple] = useState<Couple | null>(null);
  const [loading, setLoading] = useState(true);

  const status = deriveStatus(session, couple, loading);

  const fetchProfile = useCallback(async (userId: string) => {
    const { data } = await supabase
      .from('profiles')
      .select('*')
      .eq('id', userId)
      .single();
    setProfile(data as Profile | null);
    return data as Profile | null;
  }, []);

  const fetchCouple = useCallback(async (userId: string) => {
    const { data } = await supabase
      .from('couples')
      .select('*')
      .or(`partner_1.eq.${userId},partner_2.eq.${userId}`)
      .single();
    setCouple(data as Couple | null);
    return data as Couple | null;
  }, []);

  const refreshCouple = useCallback(async () => {
    if (session?.user.id) {
      await fetchCouple(session.user.id);
    }
  }, [session, fetchCouple]);

  // Hydrate on mount
  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session: s } }) => {
      setSession(s);
      if (s?.user.id) {
        Promise.all([fetchProfile(s.user.id), fetchCouple(s.user.id)]).finally(
          () => setLoading(false),
        );
      } else {
        setLoading(false);
      }
    });

    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((_event, s) => {
      setSession(s);
      if (s?.user.id) {
        fetchProfile(s.user.id);
        fetchCouple(s.user.id);
      } else {
        setProfile(null);
        setCouple(null);
      }
    });

    return () => subscription.unsubscribe();
  }, [fetchProfile, fetchCouple]);

  const signUp = useCallback(async (email: string, password: string) => {
    const { error } = await supabase.auth.signUp({ email, password });
    if (error) throw error;
  }, []);

  const signIn = useCallback(async (email: string, password: string) => {
    const { error } = await supabase.auth.signInWithPassword({ email, password });
    if (error) throw error;
  }, []);

  const signOut = useCallback(async () => {
    await supabase.auth.signOut();
    setSession(null);
    setProfile(null);
    setCouple(null);
  }, []);

  const createCoupleAction = useCallback(async (): Promise<string> => {
    if (!session?.user.id) throw new Error('Not authenticated');
    const { data, error } = await supabase
      .from('couples')
      .insert({ partner_1: session.user.id } as any)
      .select('invite_code')
      .single();
    if (error) throw error;
    await fetchCouple(session.user.id);
    return (data as any).invite_code;
  }, [session, fetchCouple]);

  const joinCoupleAction = useCallback(
    async (code: string) => {
      const { error } = await supabase.rpc('join_couple', { code } as any);
      if (error) throw error;
      if (session?.user.id) {
        await fetchCouple(session.user.id);
      }
    },
    [session, fetchCouple],
  );

  const updateProfileAction = useCallback(
    async (data: Partial<Profile>) => {
      if (!session?.user.id) return;
      const { error } = await supabase
        .from('profiles')
        .update(data as any)
        .eq('id', session.user.id);
      if (error) throw error;
      await fetchProfile(session.user.id);
    },
    [session, fetchProfile],
  );

  const updateCoupleAction = useCallback(
    async (data: Partial<Couple>) => {
      if (!couple?.id) return;
      const { error } = await supabase
        .from('couples')
        .update(data as any)
        .eq('id', couple.id);
      if (error) throw error;
      if (session?.user.id) await fetchCouple(session.user.id);
    },
    [couple, session, fetchCouple],
  );

  return createElement(
    AuthContext.Provider,
    {
      value: {
        session,
        profile,
        couple,
        status,
        signUp,
        signIn,
        signOut,
        createCouple: createCoupleAction,
        joinCouple: joinCoupleAction,
        updateProfile: updateProfileAction,
        updateCouple: updateCoupleAction,
        refreshCouple,
      },
    },
    children,
  );
}
