import * as ImageManipulator from 'expo-image-manipulator';

import { supabase } from './supa';
import type { Photo } from '@/types/database';

export async function compressPhoto(uri: string): Promise<string> {
  const result = await ImageManipulator.manipulateAsync(
    uri,
    [{ resize: { width: 1200 } }],
    { compress: 0.8, format: ImageManipulator.SaveFormat.JPEG },
  );
  return result.uri;
}

export async function uploadPhoto(
  coupleId: string,
  localUri: string,
): Promise<string> {
  const timestamp = Date.now();
  const storagePath = `${coupleId}/${timestamp}.jpg`;

  const response = await fetch(localUri);
  const blob = await response.blob();
  const arrayBuffer = await new Response(blob).arrayBuffer();

  const { error } = await supabase.storage
    .from('couple-photos')
    .upload(storagePath, arrayBuffer, {
      contentType: 'image/jpeg',
      upsert: false,
    });

  if (error) throw error;
  return storagePath;
}

export async function insertPhotoRow(
  coupleId: string,
  senderId: string,
  storagePath: string,
  caption?: string,
): Promise<Photo> {
  const { data, error } = await supabase
    .from('photos')
    .insert({
      couple_id: coupleId,
      sender_id: senderId,
      storage_path: storagePath,
      caption: caption || null,
    } as any)
    .select('*')
    .single();

  if (error) throw error;
  return data as Photo;
}

export function getPhotoUrl(storagePath: string): string {
  const { data } = supabase.storage
    .from('couple-photos')
    .getPublicUrl(storagePath);
  return data.publicUrl;
}

export async function fetchPhotos(
  coupleId: string,
  limit = 20,
  before?: string,
): Promise<Photo[]> {
  let query = supabase
    .from('photos')
    .select('*')
    .eq('couple_id', coupleId)
    .order('created_at', { ascending: false })
    .limit(limit);

  if (before) {
    query = query.lt('created_at', before);
  }

  const { data, error } = await query;
  if (error) throw error;
  return (data as Photo[]) ?? [];
}

export async function updateReaction(
  photoId: string,
  reaction: string | null,
): Promise<void> {
  const { error } = await supabase
    .from('photos')
    .update({ reaction } as any)
    .eq('id', photoId);
  if (error) throw error;
}

export function subscribeToPhotos(
  coupleId: string,
  onNew: (photo: Photo) => void,
  onUpdate: (photo: Photo) => void,
) {
  const channel = supabase
    .channel(`couple:${coupleId}:photos`)
    .on(
      'postgres_changes',
      {
        event: 'INSERT',
        schema: 'public',
        table: 'photos',
        filter: `couple_id=eq.${coupleId}`,
      },
      (payload) => {
        onNew(payload.new as Photo);
      },
    )
    .on(
      'postgres_changes',
      {
        event: 'UPDATE',
        schema: 'public',
        table: 'photos',
        filter: `couple_id=eq.${coupleId}`,
      },
      (payload) => {
        onUpdate(payload.new as Photo);
      },
    )
    .subscribe();

  return channel;
}
