import { useRef, useState } from 'react';
import { StyleSheet, View } from 'react-native';
import { CameraView, useCameraPermissions, CameraType } from 'expo-camera';
import * as Haptics from 'expo-haptics';
import { router } from 'expo-router';

import { CameraControls } from '@/components/camera/CameraControls';
import { PhotoPreview } from '@/components/camera/PhotoPreview';
import { Text } from '@/components/ui/Text';
import { Button } from '@/components/ui/Button';
import { useAuth } from '@/lib/auth';
import { supabase } from '@/lib/supa';
import { compressPhoto, uploadPhoto, insertPhotoRow } from '@/lib/photos';
import { sendPhotoNotification } from '@/lib/notifications';
import { colors } from '@/constants/colors';
import { spacing } from '@/constants/spacing';

export default function CameraScreen() {
  const { session, couple, profile } = useAuth();
  const cameraRef = useRef<CameraView>(null);
  const [permission, requestPermission] = useCameraPermissions();
  const [facing, setFacing] = useState<CameraType>('back');
  const [photoUri, setPhotoUri] = useState<string | null>(null);
  const [sending, setSending] = useState(false);

  const userId = session?.user.id;
  const coupleId = couple?.id;
  const partnerId = couple
    ? couple.partner_1 === userId
      ? couple.partner_2
      : couple.partner_1
    : null;

  if (!permission) {
    return <View style={styles.container} />;
  }

  if (!permission.granted) {
    return (
      <View style={styles.permissionScreen}>
        <Text variant="title2" color="ink" style={styles.permissionTitle}>
          Share moments
        </Text>
        <Text variant="body" color="inkSoft" style={styles.permissionBody}>
          Allow camera access to capture and share photos with your partner.
        </Text>
        <Button onPress={requestPermission}>Allow Camera</Button>
        <Button variant="tertiary" onPress={() => router.back()}>
          Not now
        </Button>
      </View>
    );
  }

  const handleCapture = async () => {
    if (!cameraRef.current) return;
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    const photo = await cameraRef.current.takePictureAsync({
      quality: 0.9,
    });
    if (photo?.uri) {
      setPhotoUri(photo.uri);
    }
  };

  const handleFlip = () => {
    setFacing((prev) => (prev === 'back' ? 'front' : 'back'));
  };

  const handleRetake = () => {
    setPhotoUri(null);
  };

  const handleSend = async (caption: string) => {
    if (!userId || !coupleId || !photoUri) return;
    setSending(true);

    try {
      const compressed = await compressPhoto(photoUri);
      const storagePath = await uploadPhoto(coupleId, compressed);
      await insertPhotoRow(coupleId, userId, storagePath, caption);

      Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);

      // Send push notification to partner
      if (partnerId) {
        const { data: partnerData } = await supabase
          .from('profiles')
          .select('push_token')
          .eq('id', partnerId)
          .single();

        const partnerToken = (partnerData as any)?.push_token;
        if (partnerToken) {
          const senderName = profile?.display_name || 'Your love';
          sendPhotoNotification(partnerToken, senderName);
        }
      }

      router.back();
    } catch (error) {
      console.error('Failed to send photo:', error);
      setSending(false);
    }
  };

  if (photoUri) {
    return (
      <PhotoPreview
        uri={photoUri}
        onSend={handleSend}
        onRetake={handleRetake}
        sending={sending}
      />
    );
  }

  return (
    <View style={styles.container}>
      <CameraView
        ref={cameraRef}
        style={styles.camera}
        facing={facing}
      />
      <CameraControls
        onClose={() => router.back()}
        onFlip={handleFlip}
        onCapture={handleCapture}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#000',
  },
  camera: {
    flex: 1,
  },
  permissionScreen: {
    flex: 1,
    backgroundColor: colors.cream,
    alignItems: 'center',
    justifyContent: 'center',
    paddingHorizontal: spacing[32],
    gap: spacing[16],
  },
  permissionTitle: {
    textAlign: 'center',
  },
  permissionBody: {
    textAlign: 'center',
    marginBottom: spacing[8],
  },
});
