import { useCallback, useEffect, useState } from 'react';
import { formatDistanceToNow } from 'date-fns';

import { useAuth } from '@/lib/auth';
import { supabase } from '@/lib/supa';
import type { Tap, Photo, LoveNote, DailyQuestion } from '@/types/database';

export type ActivityItem =
  | { type: 'tap'; data: Tap; timestamp: string; relativeTime: string }
  | { type: 'photo'; data: Photo; timestamp: string; relativeTime: string }
  | { type: 'note'; data: LoveNote; timestamp: string; relativeTime: string }
  | { type: 'question'; data: DailyQuestion; timestamp: string; relativeTime: string };

function relative(ts: string): string {
  return formatDistanceToNow(new Date(ts), { addSuffix: true });
}

export function useRecentActivity() {
  const { session, couple } = useAuth();
  const userId = session?.user.id;
  const coupleId = couple?.id;

  const [activities, setActivities] = useState<ActivityItem[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchAll = useCallback(async () => {
    if (!coupleId) return;
    setLoading(true);

    const [tapsRes, photosRes, notesRes, questionsRes] = await Promise.all([
      supabase
        .from('taps')
        .select('*')
        .eq('couple_id', coupleId)
        .order('created_at', { ascending: false })
        .limit(5),
      supabase
        .from('photos')
        .select('*')
        .eq('couple_id', coupleId)
        .order('created_at', { ascending: false })
        .limit(5),
      supabase
        .from('love_notes')
        .select('*')
        .eq('couple_id', coupleId)
        .eq('delivered', true)
        .order('created_at', { ascending: false })
        .limit(5),
      supabase
        .from('daily_questions')
        .select('*')
        .eq('couple_id', coupleId)
        .order('created_at', { ascending: false })
        .limit(3),
    ]);

    const items: ActivityItem[] = [];

    (tapsRes.data as Tap[] | null)?.forEach((t) =>
      items.push({ type: 'tap', data: t, timestamp: t.created_at, relativeTime: relative(t.created_at) }),
    );
    (photosRes.data as Photo[] | null)?.forEach((p) =>
      items.push({ type: 'photo', data: p, timestamp: p.created_at, relativeTime: relative(p.created_at) }),
    );
    (notesRes.data as LoveNote[] | null)?.forEach((n) =>
      items.push({ type: 'note', data: n, timestamp: n.created_at, relativeTime: relative(n.created_at) }),
    );
    (questionsRes.data as DailyQuestion[] | null)?.forEach((q) =>
      items.push({ type: 'question', data: q, timestamp: q.created_at, relativeTime: relative(q.created_at) }),
    );

    items.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
    setActivities(items.slice(0, 10));
    setLoading(false);
  }, [coupleId]);

  useEffect(() => {
    fetchAll();
  }, [fetchAll]);

  return { activities, loading, refresh: fetchAll, userId };
}
