import { Pressable, StyleSheet } from 'react-native';
import * as Haptics from 'expo-haptics';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withSequence,
  withSpring,
} from 'react-native-reanimated';
import { Heart } from 'lucide-react-native';

import { colors } from '@/constants/colors';
import { springs } from '@/constants/animations';

interface HeartReactionProps {
  active: boolean;
  onToggle: () => void;
}

export function HeartReaction({ active, onToggle }: HeartReactionProps) {
  const scale = useSharedValue(1);

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: scale.value }],
  }));

  const handlePress = () => {
    scale.value = withSequence(
      withSpring(0.7, springs.snappy),
      withSpring(1.3, springs.bouncy),
      withSpring(1, springs.gentle),
    );
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    onToggle();
  };

  return (
    <Pressable onPress={handlePress} hitSlop={8}>
      <Animated.View style={animatedStyle}>
        <Heart
          size={22}
          color={active ? colors.rose : colors.inkFaint}
          fill={active ? colors.rose : 'transparent'}
          strokeWidth={1.5}
        />
      </Animated.View>
    </Pressable>
  );
}
