import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  ActivityIndicator,
  FlatList,
  StyleSheet,
  View,
} from 'react-native';
import { router } from 'expo-router';
import { format } from 'date-fns';

import { ScreenWrapper } from '@/components/ui/ScreenWrapper';
import { Text } from '@/components/ui/Text';
import { PhotoCard } from '@/components/moments/PhotoCard';
import { DateDivider } from '@/components/moments/DateDivider';
import { NewPhotoAnimation } from '@/components/moments/NewPhotoAnimation';
import { CameraFAB } from '@/components/moments/CameraFAB';
import { useAuth } from '@/lib/auth';
import { supabase } from '@/lib/supa';
import {
  fetchPhotos,
  updateReaction,
  subscribeToPhotos,
} from '@/lib/photos';
import { glass } from '@/constants/glass';
import { colors } from '@/constants/colors';
import { spacing } from '@/constants/spacing';
import type { Photo } from '@/types/database';

type FeedItem =
  | { type: 'photo'; data: Photo }
  | { type: 'divider'; date: string };

function buildFeedItems(photos: Photo[]): FeedItem[] {
  const items: FeedItem[] = [];
  let lastDate = '';

  for (const photo of photos) {
    const dateStr = format(new Date(photo.created_at), 'yyyy-MM-dd');
    if (dateStr !== lastDate) {
      items.push({ type: 'divider', date: photo.created_at });
      lastDate = dateStr;
    }
    items.push({ type: 'photo', data: photo });
  }

  return items;
}

export default function MomentsScreen() {
  const { session, couple } = useAuth();
  const userId = session?.user.id;
  const coupleId = couple?.id;
  const partnerId = couple
    ? couple.partner_1 === userId
      ? couple.partner_2
      : couple.partner_1
    : null;

  const [photos, setPhotos] = useState<Photo[]>([]);
  const [loading, setLoading] = useState(true);
  const [loadingMore, setLoadingMore] = useState(false);
  const [hasMore, setHasMore] = useState(true);
  const [partnerTimezone, setPartnerTimezone] = useState<string | null>(null);
  const [newPhotoSender, setNewPhotoSender] = useState<string | null>(null);
  const [partnerName, setPartnerName] = useState('Them');

  const flatListRef = useRef<FlatList>(null);

  // Fetch partner profile
  useEffect(() => {
    if (!partnerId) return;
    supabase
      .from('profiles')
      .select('display_name, timezone')
      .eq('id', partnerId)
      .single()
      .then(({ data }) => {
        if (data) {
          setPartnerTimezone((data as any).timezone);
          setPartnerName((data as any).display_name || 'Them');
        }
      });
  }, [partnerId]);

  // Initial fetch
  useEffect(() => {
    if (!coupleId) return;
    fetchPhotos(coupleId, 20)
      .then((data) => {
        setPhotos(data);
        setHasMore(data.length === 20);
      })
      .finally(() => setLoading(false));
  }, [coupleId]);

  // Realtime subscription
  useEffect(() => {
    if (!coupleId || !userId) return;

    const channel = subscribeToPhotos(
      coupleId,
      (newPhoto) => {
        // Don't duplicate if we sent it
        if (newPhoto.sender_id === userId) return;
        setPhotos((prev) => {
          if (prev.some((p) => p.id === newPhoto.id)) return prev;
          return [newPhoto, ...prev];
        });
        setNewPhotoSender(partnerName);
      },
      (updatedPhoto) => {
        setPhotos((prev) =>
          prev.map((p) => (p.id === updatedPhoto.id ? updatedPhoto : p)),
        );
      },
    );

    // Broadcast channel for instant reactions
    const reactionChannel = supabase
      .channel(`couple:${coupleId}:reactions`)
      .on('broadcast', { event: 'reaction' }, (payload) => {
        const msg = payload.payload as {
          photo_id: string;
          reaction: string | null;
          sender_id: string;
        };
        if (msg.sender_id === userId) return;
        setPhotos((prev) =>
          prev.map((p) =>
            p.id === msg.photo_id ? { ...p, reaction: msg.reaction } : p,
          ),
        );
      })
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
      supabase.removeChannel(reactionChannel);
    };
  }, [coupleId, userId, partnerName]);

  // Load more
  const loadMore = useCallback(async () => {
    if (!coupleId || loadingMore || !hasMore || photos.length === 0) return;
    setLoadingMore(true);

    const lastPhoto = photos[photos.length - 1];
    const more = await fetchPhotos(coupleId, 20, lastPhoto.created_at);
    setPhotos((prev) => [...prev, ...more]);
    setHasMore(more.length === 20);
    setLoadingMore(false);
  }, [coupleId, loadingMore, hasMore, photos]);

  // Handle reaction
  const handleReaction = useCallback(
    async (photoId: string, reaction: string | null) => {
      if (!coupleId || !userId) return;

      // Optimistic update
      setPhotos((prev) =>
        prev.map((p) => (p.id === photoId ? { ...p, reaction } : p)),
      );

      // Broadcast instantly
      supabase.channel(`couple:${coupleId}:reactions`).send({
        type: 'broadcast',
        event: 'reaction',
        payload: { photo_id: photoId, reaction, sender_id: userId },
      });

      // Persist
      updateReaction(photoId, reaction);
    },
    [coupleId, userId],
  );

  const feedItems = useMemo(() => buildFeedItems(photos), [photos]);

  const renderItem = useCallback(
    ({ item }: { item: FeedItem }) => {
      if (item.type === 'divider') {
        return <DateDivider date={item.date} />;
      }
      return (
        <PhotoCard
          photo={item.data}
          userId={userId!}
          partnerTimezone={partnerTimezone}
          onPress={() =>
            router.push({
              pathname: '/photo-detail',
              params: { photoId: item.data.id },
            })
          }
          onReaction={handleReaction}
        />
      );
    },
    [userId, partnerTimezone, handleReaction],
  );

  const keyExtractor = useCallback(
    (item: FeedItem, index: number) =>
      item.type === 'photo' ? item.data.id : `divider-${index}`,
    [],
  );

  if (!userId || !coupleId) return null;

  return (
    <ScreenWrapper gradient={glass.gradients.moments}>
      {/* New photo arrival animation */}
      <NewPhotoAnimation
        visible={!!newPhotoSender}
        senderName={newPhotoSender || ''}
        onDone={() => setNewPhotoSender(null)}
      />

      {loading ? (
        <View style={styles.center}>
          <ActivityIndicator color={colors.rose} />
        </View>
      ) : photos.length === 0 ? (
        <View style={styles.center}>
          <Text variant="title2" color="inkSoft">
            No moments yet
          </Text>
          <Text variant="body" color="inkFaint" style={styles.emptyBody}>
            Tap the camera button to share your first photo
          </Text>
        </View>
      ) : (
        <FlatList
          ref={flatListRef}
          data={feedItems}
          renderItem={renderItem}
          keyExtractor={keyExtractor}
          contentContainerStyle={styles.listContent}
          showsVerticalScrollIndicator={false}
          onEndReached={loadMore}
          onEndReachedThreshold={0.5}
          windowSize={5}
          maxToRenderPerBatch={3}
          ListFooterComponent={
            loadingMore ? (
              <ActivityIndicator
                color={colors.rose}
                style={styles.loadingMore}
              />
            ) : null
          }
        />
      )}

      <CameraFAB />
    </ScreenWrapper>
  );
}

const styles = StyleSheet.create({
  center: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    gap: spacing[8],
  },
  emptyBody: {
    textAlign: 'center',
    paddingHorizontal: spacing[32],
  },
  listContent: {
    paddingTop: spacing[8],
    paddingBottom: 120,
  },
  loadingMore: {
    paddingVertical: spacing[16],
  },
});
