import { memo } from 'react';
import { Pressable, StyleSheet, View } from 'react-native';
import { router } from 'expo-router';

import { GlassCard } from '@/components/ui/GlassCard';
import { Text } from '@/components/ui/Text';
import { colors } from '@/constants/colors';
import { spacing } from '@/constants/spacing';
import type { ActivityItem } from './useRecentActivity';

interface Props {
  activities: ActivityItem[];
  userId: string | undefined;
  partnerName: string;
}

function getActivityDisplay(
  item: ActivityItem,
  userId: string | undefined,
  partnerName: string,
): { emoji: string; text: string; route: string } {
  const isMe = item.type !== 'question' && item.data.sender_id === userId;
  const name = isMe ? 'You' : partnerName;

  switch (item.type) {
    case 'tap':
      return {
        emoji: item.data.emoji ?? '💕',
        text: `${name} sent a tap`,
        route: '/(tabs)/heart',
      };
    case 'photo':
      return {
        emoji: '📸',
        text: item.data.caption
          ? `${name}: ${item.data.caption}`
          : `${name} shared a photo`,
        route: '/(tabs)/moments',
      };
    case 'note': {
      if (!isMe && !item.data.read) {
        return {
          emoji: '💌',
          text: 'You have an unread love note',
          route: '/(tabs)/notes',
        };
      }
      return {
        emoji: '💌',
        text: `${name} sent a love note`,
        route: '/(tabs)/notes',
      };
    }
    case 'question': {
      const q = item.data;
      const myAnswer =
        userId === undefined
          ? null
          : q.partner_1_answer || q.partner_2_answer;
      if (!myAnswer) {
        return {
          emoji: '❓',
          text: "Today's question is waiting for your answer",
          route: '/(tabs)/notes',
        };
      }
      return {
        emoji: '❓',
        text: `${partnerName} answered today's question`,
        route: '/(tabs)/notes',
      };
    }
  }
}

export const ActivityFeed = memo(function ActivityFeed({
  activities,
  userId,
  partnerName,
}: Props) {
  if (activities.length === 0) {
    return (
      <GlassCard>
        <View style={styles.emptyContainer}>
          <Text variant="romanticSub" color="inkSoft" style={styles.emptyText}>
            Send the first tap!
          </Text>
        </View>
      </GlassCard>
    );
  }

  return (
    <GlassCard>
      <Text variant="footnote" color="inkFaint" style={styles.header}>
        Recent
      </Text>
      {activities.map((item, index) => {
        const display = getActivityDisplay(item, userId, partnerName);
        return (
          <Pressable
            key={`${item.type}-${item.timestamp}-${index}`}
            onPress={() => router.push(display.route as any)}
            style={({ pressed }) => [
              styles.row,
              pressed && styles.rowPressed,
              index < activities.length - 1 && styles.rowBorder,
            ]}
          >
            <Text style={styles.emoji}>{display.emoji}</Text>
            <Text
              variant="subheadline"
              color="ink"
              numberOfLines={1}
              style={styles.text}
            >
              {display.text}
            </Text>
            <Text variant="caption2" color="inkFaint">
              {item.relativeTime}
            </Text>
          </Pressable>
        );
      })}
    </GlassCard>
  );
});

const styles = StyleSheet.create({
  header: {
    marginBottom: spacing[8],
    textTransform: 'uppercase',
    letterSpacing: 0.5,
  },
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingVertical: spacing[12],
  },
  rowPressed: {
    opacity: 0.6,
  },
  rowBorder: {
    borderBottomWidth: StyleSheet.hairlineWidth,
    borderBottomColor: colors.separator,
  },
  emoji: {
    fontSize: 18,
    marginRight: spacing[12],
  },
  text: {
    flex: 1,
    marginRight: spacing[8],
  },
  emptyContainer: {
    alignItems: 'center',
    paddingVertical: spacing[16],
  },
  emptyText: {
    textAlign: 'center',
  },
});
