import { useEffect, useRef, useState } from 'react';
import { toZonedTime } from 'date-fns-tz';
import { format } from 'date-fns';

import { useAuth } from '@/lib/auth';
import { supabase } from '@/lib/supa';

export interface PartnerProfile {
  display_name: string | null;
  avatar_url: string | null;
  timezone: string | null;
  sleep_start: string;
  sleep_end: string;
}

interface TimeContext {
  icon: string;
  label: string;
  formattedTime: string;
  cityName: string;
}

function getTimeContext(hour: number): { icon: string; label: string } {
  if (hour >= 6 && hour < 12) return { icon: '☀️', label: 'Morning' };
  if (hour >= 12 && hour < 17) return { icon: '🌤️', label: 'Afternoon' };
  if (hour >= 17 && hour < 20) return { icon: '🌅', label: 'Evening' };
  if (hour >= 20 && hour < 23) return { icon: '🌙', label: 'Night' };
  return { icon: '💤', label: 'Sleeping' };
}

function getCityName(timezone: string): string {
  return timezone.split('/').pop()?.replace(/_/g, ' ') ?? timezone;
}

function getPartnerTimeContext(timezone: string): TimeContext {
  const now = new Date();
  const zonedTime = toZonedTime(now, timezone);
  const hour = zonedTime.getHours();
  const { icon, label } = getTimeContext(hour);
  const formattedTime = format(zonedTime, 'h:mm a');
  const cityName = getCityName(timezone);

  return { icon, label, formattedTime, cityName };
}

export function usePartnerData() {
  const { session, couple } = useAuth();
  const userId = session?.user.id;
  const coupleId = couple?.id;
  const partnerId = couple
    ? couple.partner_1 === userId
      ? couple.partner_2
      : couple.partner_1
    : null;

  const [partnerProfile, setPartnerProfile] = useState<PartnerProfile | null>(null);
  const [isOnline, setIsOnline] = useState(false);
  const [timeContext, setTimeContext] = useState<TimeContext | null>(null);
  const intervalRef = useRef<ReturnType<typeof setInterval>>(undefined);

  // Fetch partner profile
  useEffect(() => {
    if (!partnerId) return;
    supabase
      .from('profiles')
      .select('display_name, avatar_url, timezone, sleep_start, sleep_end')
      .eq('id', partnerId)
      .single()
      .then(({ data }) => {
        if (data) setPartnerProfile(data as PartnerProfile);
      });
  }, [partnerId]);

  // Update partner time context every 60s
  useEffect(() => {
    if (!partnerProfile?.timezone) return;

    const update = () => {
      setTimeContext(getPartnerTimeContext(partnerProfile.timezone!));
    };
    update();
    intervalRef.current = setInterval(update, 60_000);

    return () => {
      if (intervalRef.current) clearInterval(intervalRef.current);
    };
  }, [partnerProfile?.timezone]);

  // Supabase Presence
  useEffect(() => {
    if (!coupleId || !userId) return;

    const channel = supabase.channel(`couple:${coupleId}:home`, {
      config: { presence: { key: userId } },
    });

    channel
      .on('presence', { event: 'sync' }, () => {
        const state = channel.presenceState();
        const keys = Object.keys(state);
        setIsOnline(keys.some((k) => k !== userId));
      })
      .subscribe(async (status) => {
        if (status === 'SUBSCRIBED') {
          await channel.track({ online_at: new Date().toISOString() });
        }
      });

    return () => {
      supabase.removeChannel(channel);
    };
  }, [coupleId, userId]);

  return { partnerProfile, isOnline, timeContext, partnerId };
}
