import { useState } from 'react';
import { Alert, StyleSheet, View } from 'react-native';
import { Link } from 'expo-router';

import { ScreenWrapper } from '@/components/ui/ScreenWrapper';
import { Text } from '@/components/ui/Text';
import { Input } from '@/components/ui/Input';
import { Button } from '@/components/ui/Button';
import { useAuth } from '@/lib/auth';
import { spacing } from '@/constants/spacing';

export default function LoginScreen() {
  const { signIn } = useAuth();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);

  const handleLogin = async () => {
    if (!email || !password) return;
    setLoading(true);
    try {
      await signIn(email.trim(), password);
    } catch (e: any) {
      Alert.alert('Error', e.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <ScreenWrapper style={styles.container}>
      <View style={styles.content}>
        <Text variant="title1">Welcome back</Text>
        <Text variant="romanticSub" color="inkSoft" style={styles.subtitle}>
          we missed you
        </Text>

        <View style={styles.form}>
          <Text variant="footnote" color="inkSoft" style={styles.label}>
            Email
          </Text>
          <Input
            value={email}
            onChangeText={setEmail}
            placeholder="you@example.com"
            keyboardType="email-address"
            autoCapitalize="none"
            autoCorrect={false}
          />

          <Text variant="footnote" color="inkSoft" style={styles.label}>
            Password
          </Text>
          <Input
            value={password}
            onChangeText={setPassword}
            placeholder="Your password"
            secureTextEntry
          />
        </View>

        <Button onPress={handleLogin} loading={loading} disabled={!email || !password}>
          Log in
        </Button>

        <View style={styles.linkRow}>
          <Link href="/(auth)/signup" asChild>
            <Button variant="tertiary">Don't have an account? Sign up</Button>
          </Link>
        </View>
      </View>
    </ScreenWrapper>
  );
}

const styles = StyleSheet.create({
  container: {
    justifyContent: 'center',
  },
  content: {
    paddingBottom: spacing[48],
  },
  subtitle: {
    marginTop: spacing[8],
    marginBottom: spacing[32],
  },
  form: {
    marginBottom: spacing[24],
    gap: spacing[4],
  },
  label: {
    marginTop: spacing[12],
    marginBottom: spacing[4],
    marginLeft: spacing[4],
  },
  linkRow: {
    alignItems: 'center',
    marginTop: spacing[16],
  },
});
