// ─── Tap presets ────────────────────────────────────────────
interface TapPreset {
  emoji: string;
  label: string;
  pattern: string;
  haptic: () => Promise<void>;
}

const TAP_PRESETS: TapPreset[] = [
  {
    emoji: '💕',
    label: 'I love you',
    pattern: 'love',
    haptic: async () => {
      await Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
      await delay(80);
      await Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
      await delay(80);
      await Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
    },
  },
  {
    emoji: '🤗',
    label: 'Hug',
    pattern: 'hug',
    haptic: async () => {
      await Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Heavy);
      await delay(200);
      await Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
    },
  },
  {
    emoji: '😘',
    label: 'Kiss',
    pattern: 'kiss',
    haptic: async () => {
      await Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
      await delay(120);
      await Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    },
  },
  {
    emoji: '🌙',
    label: 'Goodnight',
    pattern: 'goodnight',
    haptic: async () => {
      await Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
      await delay(150);
      await Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Soft);
    },
  },
  {
    emoji: '☀️',
    label: 'Good morning',
    pattern: 'morning',
    haptic: async () => {
      await Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Soft);
      await delay(100);
      await Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
      await delay(100);
      await Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
    },
  },
];

function delay(ms: number) {
  return new Promise((r) => setTimeout(r, ms));
}

// ─── Ripple Component ───────────────────────────────────────
const RIPPLE_COUNT = 3;

function Ripple({ active }: { active: number }) {
  return (
    <View style={styles.rippleContainer} pointerEvents="none">
      {Array.from({ length: RIPPLE_COUNT }).map((_, i) => (
        <RippleRing key={`${active}-${i}`} index={i} trigger={active} />
      ))}
    </View>
  );
}

function RippleRing({ index, trigger }: { index: number; trigger: number }) {
  const scale = useSharedValue(0);
  const opacity = useSharedValue(0);

  useEffect(() => {
    if (trigger === 0) return;
    const delayMs = index * 150;
    scale.value = withDelay(
      delayMs,
      withTiming(2.5, { duration: 800, easing: Easing.out(Easing.cubic) }),
    );
    opacity.value = withDelay(
      delayMs,
      withSequence(
        withTiming(0.4, { duration: 100 }),
        withTiming(0, { duration: 700, easing: Easing.out(Easing.cubic) }),
      ),
    );
  }, [trigger, index, scale, opacity]);

  const style = useAnimatedStyle(() => ({
    transform: [{ scale: scale.value }],
    opacity: opacity.value,
  }));

  return <Animated.View style={[styles.rippleRing, style]} />;
}

// ─── Heart SVG ──────────────────────────────────────────────
const HEART_PATH =
  'M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z';

function BreathingHeart({ onTap }: { onTap: () => void }) {
  const breathScale = useSharedValue(1);
  const tapScale = useSharedValue(1);
  const glowOpacity = useSharedValue(0.15);

  // Breathing animation
  useEffect(() => {
    breathScale.value = withRepeat(
      withSequence(
        withSpring(1.06, { damping: 25, stiffness: 60 }),
        withSpring(1, { damping: 25, stiffness: 60 }),
      ),
      -1,
      false,
    );
    glowOpacity.value = withRepeat(
      withSequence(
        withTiming(0.3, { duration: 1500, easing: Easing.inOut(Easing.ease) }),
        withTiming(0.1, { duration: 1500, easing: Easing.inOut(Easing.ease) }),
      ),
      -1,
      false,
    );
  }, [breathScale, glowOpacity]);

  const heartStyle = useAnimatedStyle(() => ({
    transform: [{ scale: breathScale.value * tapScale.value }],
  }));

  const glowStyle = useAnimatedStyle(() => ({
    opacity: glowOpacity.value,
  }));

  const handlePress = () => {
    tapScale.value = withSequence(
      withSpring(0.85, springs.snappy),
      withSpring(1.15, springs.bouncy),
      withSpring(1, springs.gentle),
    );
    onTap();
  };

  return (
    <Pressable onPress={handlePress} style={styles.heartPressable}>
      {/* Glow layer */}
      <Animated.View style={[styles.heartGlow, glowStyle]} />
      {/* Heart */}
      <Animated.View style={heartStyle}>
        <AnimatedSvg width={140} height={140} viewBox="0 0 24 24">
          <Path d={HEART_PATH} fill={colors.rose} />
        </AnimatedSvg>
      </Animated.View>
    </Pressable>
  );
}

// ─── Bloom animation (when receiving a tap) ─────────────────
function useBloom() {
  const bloomScale = useSharedValue(1);
  const bloomOpacity = useSharedValue(0);

  const trigger = useCallback(() => {
    bloomScale.value = 1;
    bloomOpacity.value = 0.6;
    bloomScale.value = withTiming(3, { duration: 600, easing: Easing.out(Easing.cubic) });
    bloomOpacity.value = withTiming(0, { duration: 600, easing: Easing.out(Easing.cubic) });
  }, [bloomScale, bloomOpacity]);

  const style = useAnimatedStyle(() => ({
    transform: [{ scale: bloomScale.value }],
    opacity: bloomOpacity.value,
  }));

  return { trigger, style };
}

// ─── Main Screen ────────────────────────────────────────────
export default function HeartScreen() {
  const { session, couple, profile } = useAuth();
  const userId = session?.user.id;
  const coupleId = couple?.id;
  const partnerId = couple
    ? couple.partner_1 === userId
      ? couple.partner_2
      : couple.partner_1
    : null;

  const [rippleTrigger, setRippleTrigger] = useState(0);
  const [sentMessage, setSentMessage] = useState<string | null>(null);
  const [receivedMessage, setReceivedMessage] = useState<string | null>(null);
  const [partnerPresent, setPartnerPresent] = useState(false);
  const [todayTaps, setTodayTaps] = useState<Tap[]>([]);
  const [partnerProfile, setPartnerProfile] = useState<{ display_name: string | null; timezone: string | null } | null>(null);
  const sentTimeout = useRef<ReturnType<typeof setTimeout>>(undefined);
  const receivedTimeout = useRef<ReturnType<typeof setTimeout>>(undefined);

  const bloom = useBloom();

  // Fetch partner profile for timezone display
  useEffect(() => {
    if (!partnerId) return;
    supabase
      .from('profiles')
      .select('display_name, timezone')
      .eq('id', partnerId)
      .single()
      .then(({ data }) => {
        if (data) setPartnerProfile(data as any);
      });
  }, [partnerId]);

  // Fetch today's taps
  useEffect(() => {
    if (!coupleId) return;
    const todayStart = new Date();
    todayStart.setHours(0, 0, 0, 0);

    supabase
      .from('taps')
      .select('*')
      .eq('couple_id', coupleId)
      .gte('created_at', todayStart.toISOString())
      .order('created_at', { ascending: false })
      .then(({ data }) => {
        if (data) setTodayTaps(data as Tap[]);
      });
  }, [coupleId]);

  // Realtime: Broadcast channel for taps + Presence
  useEffect(() => {
    if (!coupleId || !userId) return;

    const channel = supabase.channel(`couple:${coupleId}:taps`, {
      config: { presence: { key: userId } },
    });

    channel
      .on('broadcast', { event: 'tap' }, (payload) => {
        const msg = payload.payload as {
          sender_id: string;
          pattern: string;
          emoji: string;
          timestamp: string;
        };
        if (msg.sender_id === userId) return;

        // Received a tap from partner
        const preset = TAP_PRESETS.find((p) => p.pattern === msg.pattern);
        if (preset) {
          preset.haptic();
        } else {
          Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
        }

        bloom.trigger();
        showReceivedMessage(msg.emoji);

        // Add to today's taps
        setTodayTaps((prev) => [
          {
            id: msg.timestamp,
            couple_id: coupleId,
            sender_id: msg.sender_id,
            pattern: msg.pattern,
            emoji: msg.emoji,
            created_at: msg.timestamp,
          },
          ...prev,
        ]);
      })
      .on('presence', { event: 'sync' }, () => {
        const state = channel.presenceState();
        const keys = Object.keys(state);
        setPartnerPresent(keys.some((k) => k !== userId));
      })
      .subscribe(async (status) => {
        if (status === 'SUBSCRIBED') {
          await channel.track({ online_at: new Date().toISOString() });
        }
      });

    return () => {
      supabase.removeChannel(channel);
    };
  }, [coupleId, userId, bloom]);

  const showSentMessage = (emoji: string) => {
    if (sentTimeout.current) clearTimeout(sentTimeout.current);
    setSentMessage(`Sent ${emoji}`);
    sentTimeout.current = setTimeout(() => setSentMessage(null), 1500);
  };

  const showReceivedMessage = (emoji: string) => {
    if (receivedTimeout.current) clearTimeout(receivedTimeout.current);
    setReceivedMessage(`They're thinking of you ${emoji}`);
    receivedTimeout.current = setTimeout(() => setReceivedMessage(null), 2500);
  };

  const sendTap = useCallback(
    async (pattern: string, emoji: string, hapticFn?: () => Promise<void>) => {
      if (!coupleId || !userId) return;

      // Haptic feedback
      if (hapticFn) {
        hapticFn();
      } else {
        Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
      }

      // Ripple
      setRippleTrigger((n) => n + 1);

      const timestamp = new Date().toISOString();

      // Broadcast instantly (don't await DB write)
      supabase.channel(`couple:${coupleId}:taps`).send({
        type: 'broadcast',
        event: 'tap',
        payload: { sender_id: userId, pattern, emoji, timestamp },
      });

      showSentMessage(emoji);

      // Add to local taps list
      setTodayTaps((prev) => [
        {
          id: timestamp,
          couple_id: coupleId,
          sender_id: userId,
          pattern,
          emoji,
          created_at: timestamp,
        },
        ...prev,
      ]);

      // Persist to DB (fire-and-forget)
      supabase
        .from('taps')
        .insert({ couple_id: coupleId, sender_id: userId, pattern, emoji } as any)
        .then();
    },
    [coupleId, userId],
  );

  const handleHeartTap = () => {
    sendTap('tap', '❤️');
  };

  const formatTapTime = (isoString: string, tz?: string | null) => {
    const date = new Date(isoString);
    const local = format(date, 'h:mm a');
    if (!tz) return local;
    try {
      const partnerTime = toZonedTime(date, tz);
      return `${local} (their ${format(partnerTime, 'h:mm a')})`;
    } catch {
      return local;
    }
  };

  const partnerName = partnerProfile?.display_name || 'Partner';

  return (
    <ScreenWrapper gradient={glass.gradients.heart}>
      <ScrollView
        style={styles.scroll}
        contentContainerStyle={styles.scrollContent}
        showsVerticalScrollIndicator={false}
      >
        {/* Presence indicator */}
        {partnerPresent && (
          <Animated.View entering={FadeIn.duration(300)} style={styles.presenceRow}>
            <View style={styles.presenceDot} />
            <Text variant="caption1" color="sage">
              They're here too
            </Text>
          </Animated.View>
        )}

        {/* Heart area */}
        <View style={styles.heartArea}>
          {/* Bloom layer */}
          <Animated.View style={[styles.bloomCircle, bloom.style]} />

          {/* Ripple layer */}
          <Ripple active={rippleTrigger} />

          {/* Heart */}
          <BreathingHeart onTap={handleHeartTap} />

          {/* Floating messages */}
          {sentMessage && (
            <Animated.View
              entering={FadeIn.duration(200)}
              exiting={FadeOut.duration(400)}
              style={styles.floatingMessage}
              key={`sent-${rippleTrigger}`}
            >
              <Text variant="romanticSub" color="rose">
                {sentMessage}
              </Text>
            </Animated.View>
          )}
          {receivedMessage && (
            <Animated.View
              entering={FadeIn.duration(200)}
              exiting={FadeOut.duration(600)}
              style={styles.floatingMessage}
              key={`recv-${receivedMessage}`}
            >
              <Text variant="romanticSub" color="rose">
                {receivedMessage}
              </Text>
            </Animated.View>
          )}
        </View>

        {/* Preset buttons */}
        <View style={styles.presets}>
          {TAP_PRESETS.map((preset) => (
            <Pressable
              key={preset.pattern}
              onPress={() => sendTap(preset.pattern, preset.emoji, preset.haptic)}
              style={styles.presetButton}
            >
              <Text style={styles.presetEmoji}>{preset.emoji}</Text>
              <Text variant="caption2" color="inkSoft" style={styles.presetLabel}>
                {preset.label}
              </Text>
            </Pressable>
          ))}
        </View>

        {/* Tap history */}
        {todayTaps.length > 0 && (
          <View style={styles.history}>
            <Text variant="footnote" color="inkFaint" style={styles.historyTitle}>
              Today
            </Text>
            {todayTaps.slice(0, 20).map((tap) => {
              const isMe = tap.sender_id === userId;
              const senderName = isMe ? 'You' : partnerName;
              const tz = isMe ? null : partnerProfile?.timezone;
              return (
                <View key={tap.id} style={styles.historyRow}>
                  <Text variant="caption1" color="inkSoft">
                    {senderName} sent {tap.emoji || '❤️'} at{' '}
                    {formatTapTime(tap.created_at, tz)}
                  </Text>
                </View>
              );
            })}
          </View>
        )}

        {/* Bottom spacer for tab bar */}
        <View style={{ height: 100 }} />
      </ScrollView>
    </ScreenWrapper>
  );
}

