import { useEffect, useMemo } from 'react';
import { Dimensions, StyleSheet } from 'react-native';
import Animated, {
  FadeIn,
  FadeOut,
  useAnimatedStyle,
  useSharedValue,
  withDelay,
  withTiming,
  Easing,
} from 'react-native-reanimated';

import { Text } from '@/components/ui/Text';
import { colors } from '@/constants/colors';

const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = Dimensions.get('window');

const PARTICLE_COLORS = [colors.rose, colors.gold, colors.lavender, colors.roseLight, colors.dawn];
const PARTICLE_COUNT = 16;

interface ParticleProps {
  color: string;
  angle: number;
  distance: number;
  delay: number;
  size: number;
}

function Particle({ color, angle, distance, delay, size }: ParticleProps) {
  const translateX = useSharedValue(0);
  const translateY = useSharedValue(0);
  const opacity = useSharedValue(1);
  const scale = useSharedValue(0);

  useEffect(() => {
    const targetX = Math.cos(angle) * distance;
    const targetY = Math.sin(angle) * distance;

    scale.value = withDelay(delay, withTiming(1, { duration: 200, easing: Easing.out(Easing.ease) }));
    translateX.value = withDelay(delay, withTiming(targetX, { duration: 800, easing: Easing.out(Easing.cubic) }));
    translateY.value = withDelay(delay, withTiming(targetY, { duration: 800, easing: Easing.out(Easing.cubic) }));
    opacity.value = withDelay(delay + 400, withTiming(0, { duration: 400 }));
  }, []);

  const style = useAnimatedStyle(() => ({
    transform: [
      { translateX: translateX.value },
      { translateY: translateY.value },
      { scale: scale.value },
    ],
    opacity: opacity.value,
  }));

  return (
    <Animated.View
      style={[
        {
          position: 'absolute',
          width: size,
          height: size,
          borderRadius: size / 2,
          backgroundColor: color,
        },
        style,
      ]}
    />
  );
}

interface Props {
  visible: boolean;
  onDismiss: () => void;
}

export function MilestoneCelebration({ visible, onDismiss }: Props) {
  const particles = useMemo(
    () =>
      Array.from({ length: PARTICLE_COUNT }, (_, i) => ({
        color: PARTICLE_COLORS[i % PARTICLE_COLORS.length],
        angle: (i / PARTICLE_COUNT) * Math.PI * 2,
        distance: 60 + Math.random() * 80,
        delay: Math.random() * 200,
        size: 4 + Math.random() * 6,
      })),
    [],
  );

  useEffect(() => {
    if (visible) {
      const timer = setTimeout(onDismiss, 3000);
      return () => clearTimeout(timer);
    }
  }, [visible, onDismiss]);

  if (!visible) return null;

  return (
    <Animated.View
      entering={FadeIn.duration(300)}
      exiting={FadeOut.duration(500)}
      style={styles.overlay}
      pointerEvents="none"
    >
      <Animated.View style={styles.particleContainer}>
        {particles.map((p, i) => (
          <Particle key={i} {...p} />
        ))}
      </Animated.View>
      <Text variant="romantic" color="rose" style={styles.text}>
        One day closer! {'💕'}
      </Text>
    </Animated.View>
  );
}

const styles = StyleSheet.create({
  overlay: {
    ...StyleSheet.absoluteFillObject,
    justifyContent: 'center',
    alignItems: 'center',
    zIndex: 100,
  },
  particleContainer: {
    width: 1,
    height: 1,
    alignItems: 'center',
    justifyContent: 'center',
  },
  text: {
    marginTop: 24,
    textAlign: 'center',
  },
});
