import { Text as RNText, TextProps as RNTextProps } from 'react-native';

import { colors, ColorToken } from '@/constants/colors';
import { typeScale, TypeVariant } from '@/constants/typography';

interface TextProps extends RNTextProps {
  variant?: TypeVariant;
  color?: ColorToken;
}

export function Text({
  variant = 'body',
  color = 'ink',
  style,
  ...props
}: TextProps) {
  const variantStyle = typeScale[variant];
  const isSystem = variantStyle.fontFamily === 'System';

  return (
    <RNText
      style={[
        {
          fontFamily: isSystem ? undefined : variantStyle.fontFamily,
          fontSize: variantStyle.fontSize,
          lineHeight: variantStyle.lineHeight,
          letterSpacing: variantStyle.letterSpacing,
          color: colors[color],
          ...('fontWeight' in variantStyle
            ? { fontWeight: variantStyle.fontWeight }
            : {}),
        },
        style,
      ]}
      {...props}
    />
  );
}
