import { memo } from 'react';
import { Platform, Pressable, StyleSheet, View } from 'react-native';
import * as Haptics from 'expo-haptics';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withSpring,
} from 'react-native-reanimated';
import { router } from 'expo-router';

import { Text } from '@/components/ui/Text';
import { colors } from '@/constants/colors';
import { spacing } from '@/constants/spacing';
import { springs } from '@/constants/animations';
import { glass } from '@/constants/glass';

const AnimatedPressable = Animated.createAnimatedComponent(Pressable);

interface QuickAction {
  emoji: string;
  label: string;
  route: string;
}

const ACTIONS: QuickAction[] = [
  { emoji: '💕', label: 'Quick Tap', route: '/(tabs)/heart' },
  { emoji: '📸', label: 'Send Photo', route: '/camera' },
  { emoji: '💌', label: 'Write Note', route: '/(tabs)/notes' },
  { emoji: '❓', label: "Today's Q", route: '/(tabs)/notes' },
];

function ActionButton({ action }: { action: QuickAction }) {
  const scale = useSharedValue(1);

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: scale.value }],
  }));

  const handlePressIn = () => {
    scale.value = withSpring(0.92, springs.snappy);
  };

  const handlePressOut = () => {
    scale.value = withSpring(1, springs.gentle);
  };

  const handlePress = () => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    router.push(action.route as any);
  };

  return (
    <View style={styles.actionWrapper}>
      <AnimatedPressable
        onPressIn={handlePressIn}
        onPressOut={handlePressOut}
        onPress={handlePress}
        style={[styles.button, animatedStyle]}
      >
        <Text style={styles.emoji}>{action.emoji}</Text>
      </AnimatedPressable>
      <Text variant="caption2" color="inkSoft" style={styles.label}>
        {action.label}
      </Text>
    </View>
  );
}

export const QuickActions = memo(function QuickActions() {
  return (
    <View style={styles.container}>
      {ACTIONS.map((action) => (
        <ActionButton key={action.label} action={action} />
      ))}
    </View>
  );
});

const styles = StyleSheet.create({
  container: {
    flexDirection: 'row',
    justifyContent: 'space-around',
    paddingHorizontal: spacing[8],
  },
  actionWrapper: {
    alignItems: 'center',
  },
  button: {
    width: 56,
    height: 56,
    borderRadius: 28,
    alignItems: 'center',
    justifyContent: 'center',
    backgroundColor: glass.fallback.backgroundColor,
    borderWidth: glass.fallback.borderWidth,
    borderColor: glass.fallback.borderColor,
    ...(Platform.OS === 'ios' ? { borderCurve: 'continuous' as const } : {}),
  },
  emoji: {
    fontSize: 24,
  },
  label: {
    marginTop: spacing[4],
    textAlign: 'center',
  },
});
