import { useEffect } from 'react';
import { Dimensions, StyleSheet, View } from 'react-native';
import * as Haptics from 'expo-haptics';
import Animated, {
  FadeOut,
  useAnimatedStyle,
  useSharedValue,
  withDelay,
  withSpring,
  withTiming,
  Easing,
  runOnJS,
} from 'react-native-reanimated';
import { Audio } from 'expo-av';

import { Text } from '@/components/ui/Text';
import { colors } from '@/constants/colors';

const { width: SCREEN_WIDTH } = Dimensions.get('window');
const HEART_COUNT = 10;

interface NewPhotoAnimationProps {
  visible: boolean;
  senderName: string;
  onDone: () => void;
}

function FloatingHeart({ index }: { index: number }) {
  const translateY = useSharedValue(0);
  const translateX = useSharedValue(0);
  const opacity = useSharedValue(0);
  const scale = useSharedValue(0.5);

  const startX = Math.random() * (SCREEN_WIDTH - 40);
  const delay = index * 80;

  useEffect(() => {
    opacity.value = withDelay(delay, withTiming(1, { duration: 200 }));
    translateY.value = withDelay(
      delay,
      withTiming(-300 - Math.random() * 200, {
        duration: 1500 + Math.random() * 500,
        easing: Easing.out(Easing.cubic),
      }),
    );
    translateX.value = withDelay(
      delay,
      withTiming((Math.random() - 0.5) * 60, { duration: 1500 }),
    );
    scale.value = withDelay(delay, withSpring(0.6 + Math.random() * 0.6));
    opacity.value = withDelay(
      delay + 800,
      withTiming(0, { duration: 700 }),
    );
  }, []);

  const style = useAnimatedStyle(() => ({
    transform: [
      { translateY: translateY.value },
      { translateX: translateX.value },
      { scale: scale.value },
    ],
    opacity: opacity.value,
  }));

  return (
    <Animated.View style={[{ position: 'absolute', bottom: 200, left: startX }, style]}>
      <Text style={{ fontSize: 20 }}>❤️</Text>
    </Animated.View>
  );
}

export function NewPhotoAnimation({
  visible,
  senderName,
  onDone,
}: NewPhotoAnimationProps) {
  const translateY = useSharedValue(-100);
  const opacity = useSharedValue(0);

  useEffect(() => {
    if (!visible) return;

    Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);

    // Play chime
    (async () => {
      try {
        const { sound } = await Audio.Sound.createAsync(
          require('@/assets/sounds/chime.wav'),
          { shouldPlay: true, volume: 0.6 },
        );
        sound.setOnPlaybackStatusUpdate((status) => {
          if ('didJustFinish' in status && status.didJustFinish) {
            sound.unloadAsync();
          }
        });
      } catch {}
    })();

    // Slide in banner
    opacity.value = withTiming(1, { duration: 200 });
    translateY.value = withSpring(0, { damping: 14, stiffness: 150 });

    // Auto-dismiss
    const timer = setTimeout(() => {
      opacity.value = withTiming(0, { duration: 400 });
      translateY.value = withTiming(-100, { duration: 400 });
      setTimeout(onDone, 400);
    }, 2500);

    return () => clearTimeout(timer);
  }, [visible]);

  const bannerStyle = useAnimatedStyle(() => ({
    transform: [{ translateY: translateY.value }],
    opacity: opacity.value,
  }));

  if (!visible) return null;

  return (
    <View style={styles.overlay} pointerEvents="none">
      {/* Floating hearts */}
      {Array.from({ length: HEART_COUNT }).map((_, i) => (
        <FloatingHeart key={i} index={i} />
      ))}

      {/* Banner */}
      <Animated.View style={[styles.banner, bannerStyle]}>
        <Text variant="headline" style={{ color: '#FFFFFF' }}>
          📸 {senderName} sent a moment
        </Text>
      </Animated.View>
    </View>
  );
}

const styles = StyleSheet.create({
  overlay: {
    ...StyleSheet.absoluteFillObject,
    zIndex: 100,
  },
  banner: {
    position: 'absolute',
    top: 80,
    left: 20,
    right: 20,
    backgroundColor: colors.rose,
    borderRadius: 16,
    paddingVertical: 14,
    paddingHorizontal: 20,
    alignItems: 'center',
  },
});
