import { ReactNode } from 'react';
import { Platform, Pressable, StyleSheet, View, ViewStyle } from 'react-native';
import { BlurView } from 'expo-blur';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withSpring,
} from 'react-native-reanimated';

import { colors } from '@/constants/colors';
import { shadows } from '@/constants/shadows';
import { springs } from '@/constants/animations';
import { Text } from './Text';

const AnimatedPressable = Animated.createAnimatedComponent(Pressable);

type ButtonVariant = 'primary' | 'secondary' | 'tertiary';

interface ButtonProps {
  children: ReactNode;
  variant?: ButtonVariant;
  onPress?: () => void;
  style?: ViewStyle;
  disabled?: boolean;
  loading?: boolean;
}

export function Button({
  children,
  variant = 'primary',
  onPress,
  style,
  disabled = false,
  loading = false,
}: ButtonProps) {
  const scale = useSharedValue(1);
  const isDisabled = disabled || loading;

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [{ scale: scale.value }],
    opacity: isDisabled ? 0.7 : 1,
  }));

  const pressScale = variant === 'primary' ? 0.97 : 0.98;

  const handlePressIn = () => {
    if (!isDisabled) {
      scale.value = withSpring(pressScale, springs.snappy);
    }
  };

  const handlePressOut = () => {
    scale.value = withSpring(1, springs.gentle);
  };

  if (variant === 'tertiary') {
    return (
      <AnimatedPressable
        onPress={onPress}
        onPressIn={handlePressIn}
        onPressOut={handlePressOut}
        disabled={isDisabled}
        style={[animatedStyle, style]}
      >
        {({ pressed }) => (
          <Text variant="callout" color="rose" style={pressed ? { opacity: 0.5 } : undefined}>
            {children}
          </Text>
        )}
      </AnimatedPressable>
    );
  }

  if (variant === 'secondary') {
    const inner =
      Platform.OS === 'ios' ? (
        <BlurView intensity={30} tint="light" style={styles.secondaryInner}>
          <Text variant="headline" color="rose">
            {children}
          </Text>
        </BlurView>
      ) : (
        <View style={[styles.secondaryInner, styles.secondaryFallback]}>
          <Text variant="headline" color="rose">
            {children}
          </Text>
        </View>
      );

    return (
      <AnimatedPressable
        onPress={onPress}
        onPressIn={handlePressIn}
        onPressOut={handlePressOut}
        disabled={isDisabled}
        style={[animatedStyle, style]}
      >
        {inner}
      </AnimatedPressable>
    );
  }

  // Primary
  return (
    <AnimatedPressable
      onPress={onPress}
      onPressIn={handlePressIn}
      onPressOut={handlePressOut}
      disabled={isDisabled}
      style={[animatedStyle, style]}
    >
      {({ pressed }) => (
        <View
          style={[
            styles.primaryInner,
            shadows.buttonPrimary,
            pressed && !isDisabled && styles.primaryPressed,
          ]}
        >
          <Text variant="headline" style={{ color: '#FFFFFF' }}>
            {children}
          </Text>
        </View>
      )}
    </AnimatedPressable>
  );
}

const styles = StyleSheet.create({
  primaryInner: {
    backgroundColor: colors.rose,
    borderRadius: 14,
    height: 50,
    paddingHorizontal: 24,
    alignItems: 'center',
    justifyContent: 'center',
    ...(Platform.OS === 'ios' ? { borderCurve: 'continuous' as const } : {}),
  },
  primaryPressed: {
    backgroundColor: colors.roseDark,
  },
  secondaryInner: {
    borderRadius: 14,
    height: 50,
    paddingHorizontal: 24,
    alignItems: 'center',
    justifyContent: 'center',
    overflow: 'hidden',
    borderWidth: 0.5,
    borderColor: 'rgba(255, 255, 255, 0.3)',
    ...(Platform.OS === 'ios' ? { borderCurve: 'continuous' as const } : {}),
  },
  secondaryFallback: {
    backgroundColor: 'rgba(255, 248, 242, 0.55)',
  },
});
