import { useState } from 'react';
import { Alert, StyleSheet, View } from 'react-native';
import { parse } from 'date-fns';

import { ScreenWrapper } from '@/components/ui/ScreenWrapper';
import { Text } from '@/components/ui/Text';
import { Input } from '@/components/ui/Input';
import { Button } from '@/components/ui/Button';
import { GlassCard } from '@/components/ui/GlassCard';
import { useAuth } from '@/lib/auth';
import { spacing } from '@/constants/spacing';

export default function SetupScreen() {
  const auth = useAuth();
  const [displayName, setDisplayName] = useState('');
  const [reunionDate, setReunionDate] = useState('');
  const [loading, setLoading] = useState(false);

  const detectedTimezone = Intl.DateTimeFormat().resolvedOptions().timeZone;

  const handleSubmit = async () => {
    if (!displayName.trim()) return;
    setLoading(true);
    try {
      await auth.updateProfile({
        display_name: displayName.trim(),
        timezone: detectedTimezone,
      });

      if (reunionDate.trim()) {
        const parsed = parse(reunionDate.trim(), 'MMMM d, yyyy', new Date());
        if (!isNaN(parsed.getTime())) {
          await auth.updateCouple({ reunion_date: parsed.toISOString() });
        }
      }

      await auth.refreshCouple();
    } catch (e: any) {
      Alert.alert('Error', e.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <ScreenWrapper style={styles.container}>
      <View style={styles.content}>
        <Text variant="title1">Almost there</Text>
        <Text variant="romanticSub" color="inkSoft" style={styles.subtitle}>
          just a few things about you
        </Text>

        <GlassCard style={styles.card}>
          <Text variant="footnote" color="inkSoft" style={styles.label}>
            Display name
          </Text>
          <Input
            value={displayName}
            onChangeText={setDisplayName}
            placeholder="What does your partner call you?"
          />

          <Text variant="footnote" color="inkSoft" style={styles.label}>
            Timezone
          </Text>
          <Text variant="body" style={styles.timezone}>
            {detectedTimezone}
          </Text>

          <Text variant="footnote" color="inkSoft" style={styles.label}>
            Reunion date
          </Text>
          <Input
            value={reunionDate}
            onChangeText={setReunionDate}
            placeholder="March 25, 2026"
          />
        </GlassCard>

        <Button
          onPress={handleSubmit}
          loading={loading}
          disabled={!displayName.trim()}
          style={styles.button}
        >
          Let's begin
        </Button>
      </View>
    </ScreenWrapper>
  );
}

const styles = StyleSheet.create({
  container: {
    justifyContent: 'center',
  },
  content: {
    paddingBottom: spacing[48],
  },
  subtitle: {
    marginTop: spacing[8],
    marginBottom: spacing[24],
  },
  card: {
    marginBottom: spacing[24],
  },
  label: {
    marginTop: spacing[12],
    marginBottom: spacing[4],
    marginLeft: spacing[4],
  },
  timezone: {
    paddingHorizontal: spacing[16],
    paddingVertical: spacing[12],
  },
  button: {
    width: '100%',
  },
});
