import { memo } from 'react';
import { ColorValue, Platform, StyleSheet, View } from 'react-native';
import { LinearGradient } from 'expo-linear-gradient';
import Animated, { FadeIn, SlideInDown, SlideOutUp } from 'react-native-reanimated';

import { GlassCard } from '@/components/ui/GlassCard';
import { Text } from '@/components/ui/Text';
import { colors } from '@/constants/colors';
import { spacing } from '@/constants/spacing';

interface Props {
  days: number;
  hours: number;
  minutes: number;
  seconds: number;
  isPast: boolean;
  hasReunionDate: boolean;
}

function CountdownUnit({ value, label }: { value: number; label: string }) {
  return (
    <View style={styles.unit}>
      <Animated.View
        key={value}
        entering={SlideInDown.duration(200)}
        exiting={SlideOutUp.duration(200)}
      >
        <Text variant="heroDisplay" style={styles.number}>
          {value}
        </Text>
      </Animated.View>
      <Text variant="caption1" color="inkSoft" style={styles.unitLabel}>
        {label}
      </Text>
    </View>
  );
}

function Separator() {
  return (
    <Text variant="heroDisplay" color="inkFaint" style={styles.separator}>
      :
    </Text>
  );
}

export const ReunionCountdown = memo(function ReunionCountdown({
  days,
  hours,
  minutes,
  seconds,
  isPast,
  hasReunionDate,
}: Props) {
  if (!hasReunionDate) {
    return (
      <GlassCard>
        <View style={styles.emptyContainer}>
          <Text variant="romantic" color="inkSoft" style={styles.emptyText}>
            Set your reunion date{'\n'}in Settings
          </Text>
        </View>
      </GlassCard>
    );
  }

  if (isPast) {
    return (
      <GlassCard>
        <View style={styles.container}>
          <Text variant="heroDisplay" style={styles.togetherEmoji}>
            {'💕'}
          </Text>
          <Text variant="romanticSub" color="rose" style={styles.tagline}>
            Together at last
          </Text>
        </View>
      </GlassCard>
    );
  }

  return (
    <GlassCard style={styles.cardOverride}>
      <LinearGradient
        colors={[colors.rosePale, colors.cream] as [ColorValue, ColorValue]}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 1 }}
        style={styles.gradient}
      >
        <View style={styles.container}>
          <View style={styles.countdownRow}>
            <CountdownUnit value={days} label={days === 1 ? 'day' : 'days'} />
            <Separator />
            <CountdownUnit value={hours} label={hours === 1 ? 'hr' : 'hrs'} />
            <Separator />
            <CountdownUnit value={minutes} label={minutes === 1 ? 'min' : 'mins'} />
          </View>

          <View style={styles.secondsRow}>
            <Animated.View
              key={seconds}
              entering={SlideInDown.duration(200)}
              exiting={SlideOutUp.duration(200)}
            >
              <Text variant="romantic" color="rose">
                {String(seconds).padStart(2, '0')}
              </Text>
            </Animated.View>
            <Text variant="caption1" color="inkSoft" style={styles.secondsLabel}>
              {' '}sec
            </Text>
          </View>

          <Text variant="romanticSub" color="rose" style={styles.tagline}>
            until I hold you again
          </Text>
        </View>
      </LinearGradient>
    </GlassCard>
  );
});

const styles = StyleSheet.create({
  cardOverride: {
    padding: 0,
    overflow: 'hidden',
  },
  gradient: {
    padding: spacing[24],
    borderRadius: 20,
    ...(Platform.OS === 'ios' ? { borderCurve: 'continuous' as const } : {}),
  },
  container: {
    alignItems: 'center',
  },
  countdownRow: {
    flexDirection: 'row',
    alignItems: 'flex-start',
    justifyContent: 'center',
  },
  unit: {
    alignItems: 'center',
    minWidth: 60,
  },
  number: {
    textAlign: 'center',
  },
  unitLabel: {
    marginTop: spacing[4],
    textAlign: 'center',
  },
  separator: {
    marginHorizontal: spacing[4],
    marginTop: 2,
  },
  secondsRow: {
    flexDirection: 'row',
    alignItems: 'baseline',
    marginTop: spacing[8],
    height: 32,
    overflow: 'hidden',
  },
  secondsLabel: {
    marginBottom: 2,
  },
  tagline: {
    marginTop: spacing[12],
    textAlign: 'center',
  },
  emptyContainer: {
    alignItems: 'center',
    paddingVertical: spacing[24],
  },
  emptyText: {
    textAlign: 'center',
  },
  togetherEmoji: {
    fontSize: 48,
    textAlign: 'center',
  },
});
