import { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Dimensions,
  FlatList,
  Image,
  Pressable,
  StyleSheet,
  View,
} from 'react-native';
import { router, useLocalSearchParams } from 'expo-router';
import * as MediaLibrary from 'expo-media-library';
import * as Haptics from 'expo-haptics';
import { X, Download } from 'lucide-react-native';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
} from 'react-native-reanimated';
import {
  GestureDetector,
  Gesture,
  GestureHandlerRootView,
} from 'react-native-gesture-handler';

import { Text } from '@/components/ui/Text';
import { useAuth } from '@/lib/auth';
import { fetchPhotos, getPhotoUrl } from '@/lib/photos';
import { spacing } from '@/constants/spacing';
import type { Photo } from '@/types/database';

const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = Dimensions.get('window');

function PhotoPage({ photo }: { photo: Photo }) {
  const imageUrl = getPhotoUrl(photo.storage_path);

  const scale = useSharedValue(1);
  const savedScale = useSharedValue(1);
  const translateX = useSharedValue(0);
  const translateY = useSharedValue(0);
  const savedTranslateX = useSharedValue(0);
  const savedTranslateY = useSharedValue(0);

  const pinchGesture = Gesture.Pinch()
    .onUpdate((e) => {
      scale.value = savedScale.value * e.scale;
    })
    .onEnd(() => {
      if (scale.value < 1) {
        scale.value = 1;
        savedScale.value = 1;
        translateX.value = 0;
        translateY.value = 0;
        savedTranslateX.value = 0;
        savedTranslateY.value = 0;
      } else {
        savedScale.value = scale.value;
      }
    });

  const panGesture = Gesture.Pan()
    .onUpdate((e) => {
      if (savedScale.value > 1) {
        translateX.value = savedTranslateX.value + e.translationX;
        translateY.value = savedTranslateY.value + e.translationY;
      }
    })
    .onEnd(() => {
      savedTranslateX.value = translateX.value;
      savedTranslateY.value = translateY.value;
    });

  const composedGesture = Gesture.Simultaneous(pinchGesture, panGesture);

  const imageStyle = useAnimatedStyle(() => ({
    transform: [
      { translateX: translateX.value },
      { translateY: translateY.value },
      { scale: scale.value },
    ],
  }));

  return (
    <View style={styles.page}>
      <GestureDetector gesture={composedGesture}>
        <Animated.View style={[styles.imageWrapper, imageStyle]}>
          <Image
            source={{ uri: imageUrl }}
            style={styles.fullImage}
            resizeMode="contain"
          />
        </Animated.View>
      </GestureDetector>

      {/* Caption overlay */}
      {photo.caption ? (
        <View style={styles.captionOverlay}>
          <View style={styles.captionGradient}>
            <Text variant="romanticSub" style={{ color: '#FFFFFF' }}>
              {photo.caption}
            </Text>
          </View>
        </View>
      ) : null}
    </View>
  );
}

export default function PhotoDetailScreen() {
  const { photoId } = useLocalSearchParams<{ photoId: string }>();
  const { couple } = useAuth();
  const coupleId = couple?.id;

  const [photos, setPhotos] = useState<Photo[]>([]);
  const [initialIndex, setInitialIndex] = useState(0);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    if (!coupleId) return;
    fetchPhotos(coupleId, 100).then((data) => {
      setPhotos(data);
      const idx = data.findIndex((p) => p.id === photoId);
      setInitialIndex(idx >= 0 ? idx : 0);
      setLoaded(true);
    });
  }, [coupleId, photoId]);

  const handleSave = useCallback(async () => {
    const photo = photos.find((p) => p.id === photoId);
    if (!photo) return;

    const { status } = await MediaLibrary.requestPermissionsAsync();
    if (status !== 'granted') {
      Alert.alert('Permission needed', 'Allow access to save photos to your camera roll.');
      return;
    }

    try {
      const url = getPhotoUrl(photo.storage_path);
      const response = await fetch(url);
      const blob = await response.blob();
      // Create temp file from blob
      const fileReader = new FileReader();
      const uri = await new Promise<string>((resolve) => {
        fileReader.onload = () => {
          resolve(fileReader.result as string);
        };
        fileReader.readAsDataURL(blob);
      });

      await MediaLibrary.saveToLibraryAsync(url);
      Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
      Alert.alert('Saved', 'Photo saved to your camera roll.');
    } catch {
      Alert.alert('Error', 'Could not save photo.');
    }
  }, [photos, photoId]);

  const renderItem = useCallback(
    ({ item }: { item: Photo }) => <PhotoPage photo={item} />,
    [],
  );

  if (!loaded) {
    return <View style={styles.container} />;
  }

  return (
    <GestureHandlerRootView style={styles.container}>
      {/* Top controls */}
      <View style={styles.topBar}>
        <Pressable onPress={() => router.back()} style={styles.iconButton} hitSlop={12}>
          <X size={28} color="#FFFFFF" strokeWidth={1.5} />
        </Pressable>
        <Pressable onPress={handleSave} style={styles.iconButton} hitSlop={12}>
          <Download size={24} color="#FFFFFF" strokeWidth={1.5} />
        </Pressable>
      </View>

      <FlatList
        data={photos}
        renderItem={renderItem}
        keyExtractor={(item) => item.id}
        horizontal
        pagingEnabled
        showsHorizontalScrollIndicator={false}
        initialScrollIndex={initialIndex}
        getItemLayout={(_, index) => ({
          length: SCREEN_WIDTH,
          offset: SCREEN_WIDTH * index,
          index,
        })}
      />
    </GestureHandlerRootView>
  );
}

