import { memo } from 'react';
import { StyleSheet, View } from 'react-native';

import { GlassCard } from '@/components/ui/GlassCard';
import { Avatar } from '@/components/ui/Avatar';
import { Text } from '@/components/ui/Text';
import { TimezoneOverlapBar } from './TimezoneOverlapBar';
import type { PartnerProfile } from './usePartnerData';
import { colors } from '@/constants/colors';
import { spacing } from '@/constants/spacing';

interface Props {
  partnerProfile: PartnerProfile | null;
  isOnline: boolean;
  timeContext: {
    icon: string;
    label: string;
    formattedTime: string;
    cityName: string;
  } | null;
  myTimezone: string | null;
  mySleepStart: string;
  mySleepEnd: string;
}

export const PartnerStatusBar = memo(function PartnerStatusBar({
  partnerProfile,
  isOnline,
  timeContext,
  myTimezone,
  mySleepStart,
  mySleepEnd,
}: Props) {
  if (!partnerProfile) return null;

  const showOverlap =
    myTimezone && partnerProfile.timezone;

  return (
    <GlassCard>
      <View style={styles.row}>
        <View style={styles.avatarContainer}>
          <Avatar
            uri={partnerProfile.avatar_url}
            name={partnerProfile.display_name ?? undefined}
            size="sm"
          />
          <View
            style={[
              styles.onlineDot,
              { backgroundColor: isOnline ? colors.sage : colors.inkFaint },
            ]}
          />
        </View>

        <View style={styles.info}>
          <Text variant="headline" numberOfLines={1}>
            {partnerProfile.display_name ?? 'Partner'}
          </Text>
          {timeContext && (
            <Text variant="caption1" color="inkSoft">
              {timeContext.icon} {timeContext.formattedTime} · {timeContext.label} in{' '}
              {timeContext.cityName}
            </Text>
          )}
        </View>
      </View>

      {showOverlap && (
        <TimezoneOverlapBar
          myTimezone={myTimezone!}
          mySleepStart={mySleepStart}
          mySleepEnd={mySleepEnd}
          partnerTimezone={partnerProfile.timezone!}
          partnerSleepStart={partnerProfile.sleep_start}
          partnerSleepEnd={partnerProfile.sleep_end}
        />
      )}
    </GlassCard>
  );
});

const styles = StyleSheet.create({
  row: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  avatarContainer: {
    position: 'relative',
    marginRight: spacing[12],
  },
  onlineDot: {
    position: 'absolute',
    bottom: 0,
    right: -1,
    width: 8,
    height: 8,
    borderRadius: 4,
    borderWidth: 1.5,
    borderColor: 'rgba(255, 250, 245, 0.9)',
  },
  info: {
    flex: 1,
  },
});
