import { useCallback, useState } from 'react';
import { ScrollView, StyleSheet } from 'react-native';

import { ScreenWrapper } from '@/components/ui/ScreenWrapper';
import { useAuth } from '@/lib/auth';
import { spacing } from '@/constants/spacing';

import { PartnerStatusBar } from '@/components/home/PartnerStatusBar';
import { ReunionCountdown } from '@/components/home/ReunionCountdown';
import { QuickActions } from '@/components/home/QuickActions';
import { ActivityFeed } from '@/components/home/ActivityFeed';
import { MilestoneCelebration } from '@/components/home/MilestoneCelebration';
import { usePartnerData } from '@/components/home/usePartnerData';
import { useCountdown } from '@/components/home/useCountdown';
import { useRecentActivity } from '@/components/home/useRecentActivity';

export default function HomeScreen() {
  const { profile, couple } = useAuth();
  const [showMilestone, setShowMilestone] = useState(false);

  const { partnerProfile, isOnline, timeContext } = usePartnerData();

  const onMilestone = useCallback(() => setShowMilestone(true), []);
  const dismissMilestone = useCallback(() => setShowMilestone(false), []);

  const countdown = useCountdown(couple?.reunion_date, onMilestone);
  const { activities, userId } = useRecentActivity();

  return (
    <ScreenWrapper>
      <ScrollView
        contentContainerStyle={styles.content}
        showsVerticalScrollIndicator={false}
      >
        <PartnerStatusBar
          partnerProfile={partnerProfile}
          isOnline={isOnline}
          timeContext={timeContext}
          myTimezone={profile?.timezone ?? null}
          mySleepStart={profile?.sleep_start ?? '23:00'}
          mySleepEnd={profile?.sleep_end ?? '07:00'}
        />

        <ReunionCountdown
          days={countdown.days}
          hours={countdown.hours}
          minutes={countdown.minutes}
          seconds={countdown.seconds}
          isPast={countdown.isPast}
          hasReunionDate={!!couple?.reunion_date}
        />

        <QuickActions />

        <ActivityFeed
          activities={activities}
          userId={userId}
          partnerName={partnerProfile?.display_name ?? 'Partner'}
        />
      </ScrollView>

      <MilestoneCelebration
        visible={showMilestone}
        onDismiss={dismissMilestone}
      />
    </ScreenWrapper>
  );
}

const styles = StyleSheet.create({
  content: {
    paddingTop: spacing[16],
    paddingBottom: 100,
    gap: spacing[24],
  },
});
