import { Image, Platform, Pressable, StyleSheet, View } from 'react-native';
import { formatDistanceToNow } from 'date-fns';
import { toZonedTime, format } from 'date-fns-tz';

import { Text } from '@/components/ui/Text';
import { HeartReaction } from './HeartReaction';
import { colors } from '@/constants/colors';
import { spacing } from '@/constants/spacing';
import { shadows } from '@/constants/shadows';
import { getPhotoUrl } from '@/lib/photos';
import type { Photo } from '@/types/database';

interface PhotoCardProps {
  photo: Photo;
  userId: string;
  partnerTimezone?: string | null;
  onPress: () => void;
  onReaction: (photoId: string, reaction: string | null) => void;
}

export function PhotoCard({
  photo,
  userId,
  partnerTimezone,
  onPress,
  onReaction,
}: PhotoCardProps) {
  const isMe = photo.sender_id === userId;
  const imageUrl = getPhotoUrl(photo.storage_path);

  const timeAgo = formatDistanceToNow(new Date(photo.created_at), {
    addSuffix: true,
  });

  let partnerTime = '';
  if (partnerTimezone) {
    try {
      const zoned = toZonedTime(new Date(photo.created_at), partnerTimezone);
      partnerTime = ` · ${format(zoned, 'h:mm a')} their time`;
    } catch {}
  }

  return (
    <Pressable onPress={onPress} style={[styles.card, shadows.glass]}>
      <Image source={{ uri: imageUrl }} style={styles.image} resizeMode="cover" />

      <View style={styles.content}>
        {photo.caption ? (
          <Text variant="romanticSub" color="ink" style={styles.caption}>
            {photo.caption}
          </Text>
        ) : null}

        <View style={styles.footer}>
          <Text variant="caption2" color="inkFaint">
            {isMe ? 'You' : 'Them'} · {timeAgo}{partnerTime}
          </Text>

          <HeartReaction
            active={!!photo.reaction}
            onToggle={() =>
              onReaction(photo.id, photo.reaction ? null : '❤️')
            }
          />
        </View>
      </View>
    </Pressable>
  );
}

const styles = StyleSheet.create({
  card: {
    backgroundColor: '#FFFFFF',
    borderRadius: 20,
    overflow: 'hidden',
    marginHorizontal: spacing[4],
    marginBottom: spacing[16],
    ...(Platform.OS === 'ios' ? { borderCurve: 'continuous' as const } : {}),
  },
  image: {
    width: '100%',
    aspectRatio: 3 / 4,
  },
  content: {
    padding: spacing[16],
    gap: spacing[8],
  },
  caption: {
    marginBottom: spacing[4],
  },
  footer: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
  },
});
