import { useCallback, useEffect, useRef, useState } from 'react';

interface CountdownValues {
  days: number;
  hours: number;
  minutes: number;
  seconds: number;
  isPast: boolean;
}

function computeDiff(target: Date): CountdownValues {
  const now = Date.now();
  const diff = target.getTime() - now;

  if (diff <= 0) {
    return { days: 0, hours: 0, minutes: 0, seconds: 0, isPast: true };
  }

  const totalSeconds = Math.floor(diff / 1000);
  const days = Math.floor(totalSeconds / 86400);
  const hours = Math.floor((totalSeconds % 86400) / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;

  return { days, hours, minutes, seconds, isPast: false };
}

export function useCountdown(
  reunionDate: string | null | undefined,
  onMilestone?: () => void,
) {
  const target = reunionDate ? new Date(reunionDate) : null;
  const [countdown, setCountdown] = useState<CountdownValues>(
    target ? computeDiff(target) : { days: 0, hours: 0, minutes: 0, seconds: 0, isPast: true },
  );
  const lastDaysRef = useRef<number | null>(null);
  const onMilestoneRef = useRef(onMilestone);
  onMilestoneRef.current = onMilestone;

  useEffect(() => {
    if (!target) return;

    const tick = () => {
      const next = computeDiff(target);
      setCountdown(next);

      if (
        lastDaysRef.current !== null &&
        next.days < lastDaysRef.current &&
        !next.isPast
      ) {
        onMilestoneRef.current?.();
      }
      lastDaysRef.current = next.days;
    };

    tick();
    const id = setInterval(tick, 1000);
    return () => clearInterval(id);
  }, [reunionDate]);

  return countdown;
}
